mapper.select:

	SELECT COUNT(*) FROM (

SELECT COUNT(DISTINCT r.recipe_id)
FROM RECIPE r

	JOIN RECIPE_TAG rt ON r.recipe_id = rt.recipe_id


	JOIN IRDNT_INFO ii ON r.recipe_id = ii.recipe_id



		AND r.recipe_nm_ko LIKE CONCAT('%', #{recipeNmKo}, '%')


		AND rt.tag_id IN

			#{tid}



		AND r.level_nm = #{levelNm}


		AND ii.irdnt_nm IN

			#{nm}




	GROUP BY r.recipe_id
	HAVING COUNT(DISTINCT ii.irdnt_nm) =
	${irdntNms.size}
	) AS cnt_sub

SELECT WRITER_ID
FROM RECIPE
WHERE RECIPE_ID = #{recipeId}
